"""Cymbal Children's Hospital Co-Scheduling - seed program for AlphaEvolve.

Only build_schedule() between the EVOLVE-BLOCK markers may be changed. 
It must return a list of dicts:
[{"id": str, "demandId": str, "resourceId": str, "day": str, "startTime": str, "endTime": str, "staffIds": list[str], "priority": int}, ...]
"""
import math

def str_to_mins(t: str) -> int:
    """Converts a 'HH:MM' time string to absolute minutes since midnight."""
    h, m = map(int, t.split(':'))
    return h * 60 + m


def mins_to_str(m: int) -> str:
    """Converts absolute minutes since midnight to a 'HH:MM' string."""
    return f"{m // 60:02d}:{m % 60:02d}"


def overlaps(s1: int, e1: int, s2: int, e2: int) -> bool:
    """Checks if two time intervals strictly overlap."""
    return s1 < e2 and s2 < e1


def is_staff_qualified(staff_member: dict, role: str) -> bool:
    """Immutable domain rule: Checks if a staff member has the required specialist skill or role."""
    return role in staff_member.get("skills", []) or role == staff_member.get("role")


def is_interval_free(schedule_list: list, current_time: int, end_time: int) -> bool:
    """Immutable domain rule: Checks if a resource or staff schedule is free during [current_time, end_time]."""
    for s_mins, e_mins in schedule_list:
        if overlaps(current_time, end_time, s_mins, e_mins):
            return False
    return True


# EVOLVE-BLOCK-START
def build_schedule(config):
    """Baseline heuristic: Multi-day priority greedy packing with specialist skill matching.

    Tries to schedule each demand at the earliest possible day and time slot
    where OT and qualified specialist staff are available, balancing workload.
    """
    resources = config["resources"]
    staff = config["staff"]
    demands = config["demands"]
    heuristics = config["heuristics"]
    unavailability = config.get("unavailability", [])

    days = heuristics.get("schedulingHorizon", {}).get("days", ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"])
    start_horizon = str_to_mins(heuristics["schedulingHorizon"]["startTime"])
    end_horizon = str_to_mins(heuristics["schedulingHorizon"]["endTime"])

    DAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"]

    # Helper to check if interval is free
    def is_interval_free(sched, start, end):
        for s_start, s_end in sched:
            if max(s_start, start) < min(s_end, end):
                return False
        return True

    # Helper to collect all roles/skills of a staff member
    def get_staff_roles(s):
        roles = set()
        if "role" in s:
            roles.add(s["role"])
        if "roles" in s:
            for r in s["roles"]:
                roles.add(r)
        if "skills" in s:
            for sk in s["skills"]:
                roles.add(sk)
        return roles

    staff_roles_map = {s["id"]: get_staff_roles(s) for s in staff}

    # Pre-fill unavailability slots
    resource_schedules = {r["id"]: [] for r in resources}
    for u in unavailability:
        r_id = u.get("resourceId")
        u_day = u.get("day", "Tuesday")
        d_idx = DAYS.index(u_day) if u_day in DAYS else 0
        s_mins = d_idx * 1440 + str_to_mins(u.get("startTime", "10:00"))
        e_mins = d_idx * 1440 + str_to_mins(u.get("endTime", "14:00"))
        if r_id in resource_schedules:
            resource_schedules[r_id].append((s_mins, e_mins))

    staff_schedules = {s["id"]: [] for s in staff}
    patient_schedules = {}

    schedules = []
    appt_counter = 1

    # Heuristics parameters
    min_rest_hours = heuristics.get("minRestHoursBetweenShifts", 8)
    min_rest = int(min_rest_hours * 60)

    # Sort demands by priority, then by number of required roles (descending), then by duration (descending)
    sorted_demands = sorted(demands, key=lambda d: (
        d.get("priority", 2),
        -len(d.get("requiredRoles", [])),
        -d.get("durationMinutes", 0)
    ))

    # Pre-calculate role rarity among all staff
    role_counts = {}
    for s in staff:
        for r in staff_roles_map[s["id"]]:
            role_counts[r] = role_counts.get(r, 0) + 1

    for demand in sorted_demands:
        duration = demand["durationMinutes"]
        required_roles = demand["requiredRoles"]
        demand_id = demand["id"]
        patient_id = demand["patientId"]
        priority = demand.get("priority", 2)

        # Sort required roles of the demand by rarity (Minimum Remaining Values)
        sorted_required_roles = sorted(required_roles, key=lambda r: role_counts.get(r, 0))

        best_option = None
        best_score = -float('inf')

        for d_idx, day_name in enumerate(days):
            day_offset = d_idx * 1440
            day_start = day_offset + start_horizon
            day_end = day_offset + end_horizon

            for r_idx, resource in enumerate(resources):
                r_id = resource["id"]

                # Dynamic candidate start times for this resource to avoid forced idle gaps
                candidate_times = set()
                candidate_times.add(day_start)
                for s_start, s_end in resource_schedules[r_id]:
                    if day_start <= s_end <= day_end - duration:
                        candidate_times.add(s_end)
                for t in range(day_start, day_end - duration + 1, 10):
                    candidate_times.add(t)

                filtered_times = sorted([t for t in candidate_times if day_start <= t <= day_end - duration])

                for current_time in filtered_times:
                    end_time = current_time + duration

                    # 1. Check if resource is free
                    if not is_interval_free(resource_schedules[r_id], current_time, end_time):
                        continue

                    # 2. Check if patient is free (allow multiple non-overlapping demands per patient)
                    if patient_id in patient_schedules:
                        if not is_interval_free(patient_schedules[patient_id], current_time, end_time):
                            continue

                    # 3. Try to assign staff for each required role
                    assigned_staff = []
                    assigned_ids = set()
                    total_fatigue_penalty = 0
                    possible = True

                    for role in sorted_required_roles:
                        best_candidate = None
                        best_candidate_penalty = float('inf')

                        for s in staff:
                            s_id = s["id"]
                            if s_id in assigned_ids:
                                continue
                            if role not in staff_roles_map[s_id]:
                                continue
                            if not is_interval_free(staff_schedules[s_id], current_time, end_time):
                                continue

                            # Fatigue violation check
                            has_fatigue = False
                            for s_start, s_end in staff_schedules[s_id]:
                                if s_end > current_time - min_rest and s_start < end_time + min_rest:
                                    has_fatigue = True
                                    break

                            fatigue_penalty = 50.0 if has_fatigue else 0.0
                            workload = sum(e - st for st, e in staff_schedules[s_id])
                            penalty = fatigue_penalty + 0.001 * workload

                            if penalty < best_candidate_penalty:
                                best_candidate_penalty = penalty
                                best_candidate = s

                        if best_candidate is not None:
                            assigned_staff.append(best_candidate)
                            assigned_ids.add(best_candidate["id"])
                            total_fatigue_penalty += (50.0 if best_candidate_penalty >= 50.0 else 0.0)
                        else:
                            possible = False
                            break

                    if not possible:
                        continue

                    # Calculate idle gap
                    idle_gap = float('inf')
                    if len(resource_schedules[r_id]) == 0:
                        idle_gap = current_time - day_start
                    else:
                        for s_start, s_end in resource_schedules[r_id]:
                            if s_end <= current_time:
                                idle_gap = min(idle_gap, current_time - s_end)
                            if s_start >= end_time:
                                idle_gap = min(idle_gap, s_start - end_time)

                    if idle_gap == float('inf'):
                        idle_gap = current_time - day_start

                    # Option scoring: minimize fatigue, day index, resource index, start time, and idle gaps
                    option_score = - (total_fatigue_penalty * 1000) - (d_idx * 100) - (r_idx * 0.1) - (current_time * 0.01) - (idle_gap * 0.1)

                    if option_score > best_score:
                        best_score = option_score
                        best_option = {
                            "day_name": day_name,
                            "day_offset": day_offset,
                            "current_time": current_time,
                            "end_time": end_time,
                            "resource": resource,
                            "assigned_staff": assigned_staff
                        }

        if best_option is not None:
            day_name = best_option["day_name"]
            day_offset = best_option["day_offset"]
            current_time = best_option["current_time"]
            end_time = best_option["end_time"]
            resource = best_option["resource"]
            assigned_staff = best_option["assigned_staff"]

            start_str = mins_to_str(current_time - day_offset)
            end_str = mins_to_str(end_time - day_offset)

            schedules.append({
                "id": f"A{appt_counter}",
                "demandId": demand_id,
                "resourceId": resource["id"],
                "day": day_name,
                "startTime": start_str,
                "endTime": end_str,
                "staffIds": [s["id"] for s in assigned_staff],
                "priority": priority
            })
            appt_counter += 1

            resource_schedules[resource["id"]].append((current_time, end_time))
            for s in assigned_staff:
                staff_schedules[s["id"]].append((current_time, end_time))

            if patient_id not in patient_schedules:
                patient_schedules[patient_id] = []
            patient_schedules[patient_id].append((current_time, end_time))

    return schedules
# EVOLVE-BLOCK-END

def solve(config):
    """Entrypoint function called directly by the AlphaEvolve engine."""
    return build_schedule(config)

