        if overlaps(current_time, end_time, s_mins, e_mins):
            return False
    return True


# EVOLVE-BLOCK-START
def build_schedule(config):
    """Optimized greedy scheduling with minimum staff set covering,
    smart gap packing, and soft-rest constraints to eliminate fatigue violations.
    """
    resources = config["resources"]
    staff = config["staff"]
    demands = config["demands"]
    heuristics = config["heuristics"]
    unavailability = config.get("unavailability", [])

    days = heuristics.get("schedulingHorizon", {}).get("days", ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"])
    start_horizon = str_to_mins(heuristics["schedulingHorizon"]["startTime"])
    end_horizon = str_to_mins(heuristics["schedulingHorizon"]["endTime"])

    DAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]

    # Pre-fill unavailability slots
    resource_schedules = {r["id"]: [] for r in resources}
    staff_schedules = {s["id"]: [] for s in staff}

    for u in unavailability:
        u_day = u.get("day", "Tuesday")
        d_idx = DAYS.index(u_day) if u_day in DAYS else 0
        s_mins = d_idx * 1440 + str_to_mins(u.get("startTime", "10:00"))
        e_mins = d_idx * 1440 + str_to_mins(u.get("endTime", "14:00"))

        r_id = u.get("resourceId")
        if r_id and r_id in resource_schedules:
            resource_schedules[r_id].append((s_mins, e_mins))

        s_id = u.get("staffId")
        if s_id and s_id in staff_schedules:
            staff_schedules[s_id].append((s_mins, e_mins))

    patient_schedules = {}

    min_rest_hours = heuristics.get("minRestHoursBetweenShifts", config.get("minRestHoursBetweenShifts", 8))
    min_rest_mins = int(min_rest_hours * 60)

    schedules = []
    appt_counter = 1

    # Sort demands: Emergency (0) > Urgent (1) > Routine (2)
    # Then schedule shorter surgeries first to maximize throughput
    sorted_demands = sorted(demands, key=lambda d: (d.get("priority", 2), d.get("durationMinutes", 0)))

    def find_staff_combination(required_roles, candidates):
        # Sort candidates: prioritize those who satisfy more roles, then those with less workload
        candidates_sorted = sorted(
            candidates,
            key=lambda c: (
                -len([r for r in required_roles if is_staff_qualified(c, r)]),
                sum(e - st for st, e in staff_schedules[c["id"]])
            )
        )

        cand_roles = {}
        for c in candidates_sorted:
            covered = [r for r in required_roles if is_staff_qualified(c, r)]
            if covered:
                cand_roles[c["id"]] = (c, set(covered))

        best_combination = None

        def search(index, current_covered, current_selection):
            nonlocal best_combination
            if len(current_covered) == len(required_roles):
                if best_combination is None or len(current_selection) < len(best_combination):
                    best_combination = list(current_selection)
                return
            if best_combination is not None and len(current_selection) >= len(best_combination):
                return
            if index >= len(candidates_sorted):
                return

            # Option 1: Include
            c = candidates_sorted[index]
            c_roles = cand_roles.get(c["id"])
            if c_roles:
                new_covered = current_covered | c_roles[1]
                if len(new_covered) > len(current_covered):
                    search(index + 1, new_covered, current_selection + [c])

            # Option 2: Exclude
            search(index + 1, current_covered, current_selection)

        search(0, set(), [])
        return best_combination

    def is_staff_fatigue_free(staff_id, start, end):
        for s_start, s_end in staff_schedules[staff_id]:
            if overlaps(start, end, s_start - min_rest_mins, s_end + min_rest_mins):
                return False
        return True

    def get_free_intervals(busy_list, day_start, day_end):
        intervals = []
        for s, e in busy_list:
            if e <= day_start or s >= day_end:
                continue
            intervals.append((max(s, day_start), min(e, day_end)))
