    for u in unavailability:
        u_day = u.get("day")
        if u_day not in day_to_idx:
            continue
        d_idx = day_to_idx[u_day]
        s_mins = d_idx * 1440 + str_to_mins(u.get("startTime", "10:00"))
        e_mins = d_idx * 1440 + str_to_mins(u.get("endTime", "14:00"))

        r_id = u.get("resourceId")
        if r_id and r_id in resource_schedules:
            resource_schedules[r_id].append((s_mins, e_mins))

        s_id = u.get("staffId")
        if s_id and s_id in staff_schedules:
            staff_schedules[s_id].append((s_mins, e_mins))

    # Helper to check if interval is free
    def is_interval_free(schedule, start, end):
        for s_start, s_end in schedule:
            if overlaps(s_start, s_end, start, end):
                return False
        return True

    # Helper to check if staff member has a role or skill
    def staff_has_role(s, role):
        roles = s.get("roles", []) or s.get("skills", [])
        if isinstance(roles, str):
            roles = [roles]
        if "role" in s and s["role"]:
            roles = list(roles) + [s["role"]]
        if "skill" in s and s["skill"]:
            roles = list(roles) + [s["skill"]]
        return role in roles

    # Helper to count fatigue violations
    def count_fatigue_violations(staff_id, start_time, end_time):
        violations = 0
        for s_st, s_ed in staff_schedules[staff_id]:
            if overlaps(s_st - rest_period, s_ed + rest_period, start_time, end_time):
