    def find_covering_staff(current_time, end_time, required_roles):
        available_staff = []
        for s in staff:
            s_id = s["id"]
            if is_interval_free(staff_schedules[s_id], current_time, end_time):
                fatigue_v = count_fatigue_violations(s_id, current_time, end_time)
                covered_roles = [r for r in required_roles if staff_has_role(s, r)]
                if covered_roles:
