            # Option 1: Include
            cand = available_staff[index]
            new_covered = covered_set | cand["covered_roles"]
            if len(new_covered) > len(covered_set):
                current_subset.append(cand["staff"])
                search(
                    index + 1, 
                    current_subset, 
                    new_covered, 
                    total_fatigue + cand["fatigue"], 
                    total_workload + cand["workload"]
                )
                current_subset.pop()

            # Option 2: Exclude
            search(index + 1, current_subset, covered_set, total_fatigue, total_workload)

        # Quick check for single staff cover with 0 fatigue
        for cand in available_staff:
            if len(cand["covered_roles"]) == len(required_roles) and cand["fatigue"] == 0:
                return [cand["staff"]]

        available_staff.sort(key=lambda x: (x["fatigue"], -len(x["covered_roles"]), x["workload"]))
