                candidate_starts = set()
                candidate_starts.add(day_start)
                if day_end - duration >= day_start:
                    candidate_starts.add(day_end - duration)

                for s_st, s_ed in r_sched:
                    if day_start <= s_ed <= day_end - duration:
                        candidate_starts.add(s_ed)
                    if day_start <= s_st - duration <= day_end - duration:
                        candidate_starts.add(s_st - duration)

                for s in staff:
                    s_id = s["id"]
                    for s_st, s_ed in staff_schedules[s_id]:
                        if day_start <= s_ed <= day_end - duration:
                            candidate_starts.add(s_ed)
                        if day_start <= s_ed + rest_period <= day_end - duration:
                            candidate_starts.add(s_ed + rest_period)
                        if day_start <= s_st - duration <= day_end - duration:
                            candidate_starts.add(s_st - duration)
                        if day_start <= s_st - rest_period - duration <= day_end - duration:
                            candidate_starts.add(s_st - rest_period - duration)

                if patient_id in patient_schedules:
                    for p_st, p_ed in patient_schedules[patient_id]:
                        if day_start <= p_ed <= day_end - duration:
                            candidate_starts.add(p_ed)
                        if day_start <= p_st - duration <= day_end - duration:
                            candidate_starts.add(p_st - duration)

                starts = sorted(list(candidate_starts))

                for current_time in starts:
                    end_time = current_time + duration

                    # 1. Resource free check
                    if not is_interval_free(r_sched, current_time, end_time):
                        continue

                    # 2. Patient free check
                    if patient_id in patient_schedules:
                        if not is_interval_free(patient_schedules[patient_id], current_time, end_time):
                            continue

                    # 3. Find covering staff
                    assigned_staff = find_covering_staff(current_time, end_time, required_roles)
                    if not assigned_staff:
                        continue

                    # Calculate total fatigue violations for this assignment
                    fatigue_count = sum(count_fatigue_violations(s["id"], current_time, end_time) for s in assigned_staff)

                    # Calculate gap on the resource (to both left and right neighbors)
                    closest_prev_end = day_start
                    closest_next_start = day_end
                    for s_st, s_ed in r_sched:
                        if s_ed <= current_time and s_ed > closest_prev_end:
                            closest_prev_end = s_ed
                        if s_st >= end_time and s_st < closest_next_start:
                            closest_next_start = s_st

                    gap_left = current_time - closest_prev_end
                    gap_right = closest_next_start - end_time
                    gap = min(gap_left, gap_right)

                    # Candidate score: minimize fatigue, prefer smaller resource gap, fewer staff, prefer earlier days, earlier starts
                    candidate_score = (fatigue_count, gap, len(assigned_staff), d_idx, current_time)

                    if best_slot is None or candidate_score < best_slot["score"]:
                        best_slot = {
                            "score": candidate_score,
                            "day_name": day_name,
                            "current_time": current_time,
                            "end_time": end_time,
                            "resource": r,
                            "staff": assigned_staff
                        }

        if best_slot:
            # Commit the scheduled appointment
            current_time = best_slot["current_time"]
            end_time = best_slot["end_time"]
            r_id = best_slot["resource"]["id"]
            assigned_staff = best_slot["staff"]
            day_name = best_slot["day_name"]
            day_offset = day_to_idx[day_name] * 1440

            schedules.append({
                "id": f"A{appt_counter}",
                "demandId": demand_id,
                "resourceId": r_id,
                "day": day_name,
                "startTime": mins_to_str(current_time - day_offset),
                "endTime": mins_to_str(end_time - day_offset),
                "staffIds": [s["id"] for s in assigned_staff]
            })
            appt_counter += 1

            resource_schedules[r_id].append((current_time, end_time))
            for s in assigned_staff:
                staff_schedules[s["id"]].append((current_time, end_time))

            if patient_id not in patient_schedules:
                patient_schedules[patient_id] = []
            patient_schedules[patient_id].append((current_time, end_time))

    return schedules
