            end_time = start_time + duration
            d_idx = DAYS.index(day_name)
            day_offset = d_idx * 1440

            start_str = mins_to_str(start_time - day_offset)
            end_str = mins_to_str(end_time - day_offset)

            schedules.append({
                "id": f"A{appt_counter}",
                "demandId": demand_id,
                "resourceId": r["id"],
                "day": day_name,
                "startTime": start_str,
                "endTime": end_str,
                "staffIds": [s["id"] for s in assigned_staff],
                "priority": priority
            })
            appt_counter += 1

            resource_schedules[r["id"]].append((start_time, end_time))
            for s in assigned_staff:
                staff_schedules[s["id"]].append((start_time, end_time))
            patient_schedules[patient_id].append((start_time, end_time))

