            candidate_times = sorted(list(smart_times))

            for start_time in candidate_times:
                end_time = start_time + duration
                if end_time > day_end:
                    continue

                # Pruning: if we have a perfect back-to-back slot with 0 fatigue, no later slot can beat it
                if best_score[0] == 0 and best_score[1] == 0 and start_time >= best_score[2]:
                    break

                if not is_free(patient_schedules[patient_id], start_time, end_time):
                    continue

                for r in resources:
                    r_id = r["id"]
                    if not is_free(resource_schedules[r_id], start_time, end_time):
                        continue

                    # Staff selection
                    assigned_staff = []
                    role_satisfied = True
                    for role in sorted_roles:
                        assigned_ids = {st["id"] for st in assigned_staff}
                        candidates = [
                            s for s in staff 
                            if is_staff_qualified(s, role) and s["id"] not in assigned_ids
                        ]
                        free_candidates = [
                            s for s in candidates 
                            if is_free(staff_schedules[s["id"]], start_time, end_time)
                        ]
                        if not free_candidates:
                            role_satisfied = False
                            break

                        # Sort by minimizing fatigue first, then workload
                        free_candidates.sort(key=lambda s: (
                            get_fatigue_score(s["id"], start_time, end_time),
                            sum(e - st for st, e in staff_schedules[s["id"]])
                        ))
                        assigned_staff.append(free_candidates[0])

                    if role_satisfied:
                        fatigue_violations = sum(get_fatigue_score(s["id"], start_time, end_time) for s in assigned_staff)

                        # Calculate resource gap to minimize idle time
                        r_appts = resource_schedules[r_id]
                        prev_end = day_start
                        for s, e in r_appts:
                            if e <= start_time:
                                if e > prev_end:
                                    prev_end = e
                        gap_cost = start_time - prev_end

                        score = (fatigue_violations, gap_cost, start_time)
                        if score < best_score:
                            best_score = score
                            best_slot = (day_name, start_time, r, assigned_staff)

        if best_slot:
            day_name, start_time, r, assigned_staff = best_slot
            end_time = start_time + duration
            d_idx = DAYS.index(day_name)
            day_offset = d_idx * 1440

            start_str = mins_to_str(start_time - day_offset)
            end_str = mins_to_str(end_time - day_offset)

            schedules.append({
                "id": f"A{appt_counter}",
                "demandId": demand_id,
                "resourceId": r["id"],
                "day": day_name,
                "startTime": start_str,
                "endTime": end_str,
                "staffIds": [s["id"] for s in assigned_staff],
                "priority": priority
            })
            appt_counter += 1

            resource_schedules[r["id"]].append((start_time, end_time))
            for s in assigned_staff:
                staff_schedules[s["id"]].append((start_time, end_time))
            patient_schedules[patient_id].append((start_time, end_time))

    return schedules
# EVOLVE-BLOCK-END

def solve(config):
    """Entrypoint function called directly by the AlphaEvolve engine."""
    return build_schedule(config)
